package com.noop.ui

import org.junit.Assert.assertEquals
import org.junit.Test

/** Expected fractions generated by the standalone Swift twin, not wearable fixtures. */
class ExperimentAdherenceTest {
    @Test fun journalYesIsCountedWithoutSensorData() {
        assertEquals(1.0, ExperimentAdherence.fraction(
            setOf("2026-10-19"), "2026-10-19", "2026-10-19", 14), 1e-12)
        assertEquals(0.4, ExperimentAdherence.fraction(
            setOf("2026-10-16", "2026-10-18"), "2026-10-15", "2026-10-19", 14), 1e-12)
    }

    @Test fun completionWindowIsCalendarBounded() {
        assertEquals(2.0 / 7.0, ExperimentAdherence.fraction(
            setOf("2026-10-01", "2026-10-16", "2026-10-21", "2026-10-22"),
            "2026-10-15", "2026-10-25", 7), 1e-12)
        assertEquals(1.0, ExperimentAdherence.fraction(
            setOf("2026-10-01", "2026-10-02", "2026-10-03", "2026-10-09"),
            "2026-10-01", "2026-10-19", 3), 1e-12)
    }

    @Test fun civilDaysIncludeDstAndNewYear() {
        assertEquals(0.4, ExperimentAdherence.fraction(
            setOf("2026-10-31", "2026-11-03"), "2026-10-30", "2026-11-03", 14), 1e-12)
        assertEquals(0.5, ExperimentAdherence.fraction(
            setOf("2026-12-31", "2027-01-02"), "2026-12-30", "2027-01-02", 14), 1e-12)
    }

    @Test fun invalidMissingAndFutureDaysDoNotCreditCompletion() {
        assertEquals(0.0, ExperimentAdherence.fraction(
            setOf("2026-10-19"), "2026-10-20", "2026-10-19", 14), 1e-12)
        assertEquals(0.0, ExperimentAdherence.fraction(
            setOf("2026-10-19"), "2026-02-30", "2026-10-19", 14), 1e-12)
        assertEquals(1.0, ExperimentAdherence.fraction(
            setOf("2026-10-19", "not-a-day"), "2026-10-19", "2026-10-19", 14), 1e-12)
        assertEquals(0.0, ExperimentAdherence.fraction(
            emptySet(), "2026-10-19", "2026-10-19", 14), 1e-12)
    }

    @Test fun sensorObservationsAfterWindowCannotExtendExperiment() {
        val observedDays = listOf("2026-10-14", "2026-10-15", "2026-10-17",
            "2026-10-21", "2026-10-22", "2026-10-30", "invalid")
        val eligible = observedDays.filter {
            ExperimentAdherence.includes(it, "2026-10-15", "2026-10-30", 7)
        }
        assertEquals(listOf("2026-10-15", "2026-10-17", "2026-10-21"), eligible)
        assertEquals(false, ExperimentAdherence.includes(
            "2026-10-21", "2026-10-15", "2026-10-19", 7))
    }

}
